(async()=>{const P="";
      const K="";
      const u=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
      const o=JSON.parse(new TextDecoder().decode(u(P)));
      let k;
      if(K){k=await crypto.subtle.importKey("raw",u(K),"AES-GCM",false,["decrypt"]);}
      else{const w=prompt("Mật khẩu:")||"";const m=await crypto.subtle.importKey("raw",new TextEncoder().encode(w),"PBKDF2",false,["deriveKey"]);k=await crypto.subtle.deriveKey({name:"PBKDF2",salt:u(o.s),iterations:o.n,hash:"SHA-256"},m,{name:"AES-GCM",length:256},false,["decrypt"]);}
      const p=await crypto.subtle.decrypt({name:"AES-GCM",iv:u(o.i)},k,u(o.d));
      (0,eval)(new TextDecoder().decode(p));
      })();